'use client';

import React, { useState, useMemo, useCallback, useEffect } from 'react';
import { fileStructureData } from '@/data/file-structure';
import type { FileNode } from '@/types';
import FileTreeView from '@/components/mednotes/FileTreeView';
import PdfViewer from '@/components/mednotes/PdfViewer';
import SummarizeModal from '@/components/mednotes/SummarizeModal';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { summarizeFile, type SummarizeFileInput } from '@/ai/flows/summarize-file';
import { useToast } from '@/hooks/use-toast';
import {
  SidebarProvider,
  Sidebar,
  SidebarHeader,
  SidebarContent,
  SidebarInset,
  SidebarTrigger,
} from '@/components/ui/sidebar';
import { NotebookText, Search, Brain, Menu } from 'lucide-react';
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";

const DUMMY_FILE_CONTENT_FOR_AI = "This is a sample text from a medical PDF file about clinical cases and practical skills. It contains various medical terms and procedures. The main goal is to understand the key points and diagnoses discussed. Specific topics might include patient assessment, common diseases, treatment protocols, and ethical considerations in medicine.";

export default function MedNotesHomePage() {
  const [selectedFile, setSelectedFile] = useState<FileNode | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [summary, setSummary] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isLoadingSummary, setIsLoadingSummary] = useState(false);
  const [expandedFolders, setExpandedFolders] = useState<Set<string>>(new Set());
  const { toast } = useToast();

  const handleFileSelect = (file: FileNode) => {
    setSelectedFile(file);
  };

  const toggleFolder = useCallback((folderId: string) => {
    setExpandedFolders(prev => {
      const newSet = new Set(prev);
      if (newSet.has(folderId)) {
        newSet.delete(folderId);
      } else {
        newSet.add(folderId);
      }
      return newSet;
    });
  }, []);

  // Auto-expand folders when searching
  useEffect(() => {
    if (searchTerm.trim()) {
      const newExpanded = new Set<string>();
      const searchRecursive = (nodes: FileNode[]) => {
        nodes.forEach(node => {
          if (node.type === 'folder') {
            const childrenMatch = node.children?.some(child => 
              child.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
              (child.type === 'folder' && child.children?.some(c => c.name.toLowerCase().includes(searchTerm.toLowerCase())))
            );
            if (node.name.toLowerCase().includes(searchTerm.toLowerCase()) || childrenMatch) {
              newExpanded.add(node.id);
              if(node.children) searchRecursive(node.children);
            }
          }
        });
      };
      searchRecursive(fileStructureData);
      setExpandedFolders(newExpanded);
    } else {
      // Optionally collapse all or retain user's manual expansions
      // For now, let's clear expansions on empty search to simplify
      // setExpandedFolders(new Set()); 
    }
  }, [searchTerm]);


  const handleSummarize = async () => {
    if (!selectedFile || !selectedFile.path) {
      toast({ title: "Error", description: "Please select a file to summarize.", variant: "destructive" });
      return;
    }
    setIsLoadingSummary(true);
    setIsModalOpen(true);
    setSummary(null);

    try {
      const input: SummarizeFileInput = {
        fileContent: selectedFile.contentPreview || DUMMY_FILE_CONTENT_FOR_AI, // Using preview or dummy content
      };
      const result = await summarizeFile(input);
      setSummary(result.summary);
      toast({ title: "Summary Ready", description: `Summary for ${selectedFile.name} generated.` });
    } catch (error) {
      console.error('Error summarizing file:', error);
      setSummary('Failed to generate summary.');
      toast({ title: "Error", description: "Could not generate summary.", variant: "destructive" });
    } finally {
      setIsLoadingSummary(false);
    }
  };
  
  const filteredFileStructure = useMemo(() => {
    if (!searchTerm.trim()) {
      return fileStructureData;
    }
    const lowerSearchTerm = searchTerm.toLowerCase();

    function rFilter(nodes: FileNode[]): FileNode[] {
       return nodes.map(node => {
        if (node.type === 'file') {
          return node.name.toLowerCase().includes(lowerSearchTerm) ? node : null;
        }
        // folder
        const filteredChildren = node.children ? rFilter(node.children) : [];
        const validChildren = filteredChildren.filter(c => c !== null) as FileNode[];
        
        if (node.name.toLowerCase().includes(lowerSearchTerm) || validChildren.length > 0) {
          return { ...node, children: validChildren };
        }
        return null;
      }).filter(node => node !== null) as FileNode[];
    }
    return rFilter(fileStructureData);
  }, [searchTerm]);


  return (
    <SidebarProvider defaultOpen>
      <div className="flex h-screen w-full">
        <Sidebar collapsible="icon" side="left" variant="sidebar" className="border-r shadow-md">
          <SidebarHeader className="p-4 border-b">
            <div className="flex items-center gap-2">
              <NotebookText className="h-8 w-8 text-primary" />
              <h1 className="text-2xl font-headline font-bold text-foreground group-data-[collapsible=icon]:hidden">
                MedNotes
              </h1>
            </div>
             <div className="relative mt-4 group-data-[collapsible=icon]:hidden">
              <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                type="search"
                placeholder="Search files..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full rounded-lg bg-background pl-8 h-10 shadow-inner"
              />
            </div>
          </SidebarHeader>
          <SidebarContent className="flex-1">
            <FileTreeView
              nodes={filteredFileStructure}
              onFileSelect={handleFileSelect}
              selectedFileId={selectedFile?.id}
              searchTerm={searchTerm}
              expandedFolders={expandedFolders}
              toggleFolder={toggleFolder}
            />
          </SidebarContent>
        </Sidebar>

        <SidebarInset className="flex-1 flex flex-col overflow-hidden bg-background">
          <header className="flex items-center justify-between p-4 border-b bg-card shadow-sm">
            <SidebarTrigger className="md:hidden">
               <Menu />
            </SidebarTrigger>
            <h2 className="text-xl font-semibold text-foreground truncate ml-2 md:ml-0">
              {selectedFile ? selectedFile.name : 'Welcome to MedNotes Navigator'}
            </h2>
            {selectedFile && (
            <Tooltip>
                <TooltipTrigger asChild>
                    <Button onClick={handleSummarize} disabled={isLoadingSummary} variant="default" size="sm" className="bg-accent hover:bg-accent/90 text-accent-foreground">
                        <Brain className="mr-2 h-4 w-4" />
                        {isLoadingSummary ? 'Summarizing...' : 'AI Summary'}
                    </Button>
                </TooltipTrigger>
                <TooltipContent>
                    <p>Generate AI summary for the selected file</p>
                </TooltipContent>
            </Tooltip>
            )}
          </header>
          <main className="flex-1 p-4 md:p-6 overflow-auto">
            <PdfViewer selectedFile={selectedFile} />
          </main>
        </SidebarInset>
      </div>

      <SummarizeModal
        isOpen={isModalOpen}
        onOpenChange={setIsModalOpen}
        summary={summary}
        fileName={selectedFile?.name || null}
        isLoading={isLoadingSummary}
      />
    </SidebarProvider>
  );
}
