'use client';

import type React from 'react';
import FileTreeItem from './FileTreeItem';
import type { FileNode } from '@/types';
import { SidebarMenu } from '@/components/ui/sidebar';
import { ScrollArea } from '@/components/ui/scroll-area';

interface FileTreeViewProps {
  nodes: FileNode[];
  onFileSelect: (file: FileNode) => void;
  selectedFileId?: string;
  searchTerm: string;
  expandedFolders: Set<string>;
  toggleFolder: (folderId: string) => void;
}

const FileTreeView: React.FC<FileTreeViewProps> = ({
  nodes,
  onFileSelect,
  selectedFileId,
  searchTerm,
  expandedFolders,
  toggleFolder,
}) => {
  const filterNodes = (nodesToFilter: FileNode[], term: string): FileNode[] => {
    if (!term.trim()) {
      return nodesToFilter;
    }
    const lowerSearchTerm = term.toLowerCase();

    function rFilter(array: FileNode[]): FileNode[] {
      return array.reduce<FileNode[]>((acc, node) => {
        if (node.type === 'file') {
          if (node.name.toLowerCase().includes(lowerSearchTerm)) {
            acc.push(node);
          }
        } else { // folder
          const filteredChildren = node.children ? rFilter(node.children) : [];
          if (node.name.toLowerCase().includes(lowerSearchTerm) || filteredChildren.length > 0) {
            acc.push({ ...node, children: filteredChildren });
            // Automatically expand folders that match or have matching children
            if (!expandedFolders.has(node.id) && term) {
               // This causes issues if called during render. Expansion should be handled by parent.
               // toggleFolder(node.id); 
            }
          }
        }
        return acc;
      }, []);
    }
    return rFilter(nodesToFilter);
  };
  
  const displayedNodes = filterNodes(nodes, searchTerm);

  return (
    <ScrollArea className="h-full flex-1">
      <SidebarMenu className="p-2">
        {displayedNodes.map((node) => (
          <FileTreeItem
            key={node.id}
            node={node}
            onFileSelect={onFileSelect}
            selectedFileId={selectedFileId}
            searchTerm={searchTerm}
            expandedFolders={expandedFolders}
            toggleFolder={toggleFolder}
            level={0}
          />
        ))}
      </SidebarMenu>
    </ScrollArea>
  );
};

export default FileTreeView;
