'use client';

import type React from 'react';
import { Button } from '@/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Loader2 } from 'lucide-react';

interface SummarizeModalProps {
  isOpen: boolean;
  onOpenChange: (isOpen: boolean) => void;
  summary: string | null;
  fileName: string | null;
  isLoading: boolean;
}

const SummarizeModal: React.FC<SummarizeModalProps> = ({
  isOpen,
  onOpenChange,
  summary,
  fileName,
  isLoading,
}) => {
  return (
    <Dialog open={isOpen} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[600px] bg-card">
        <DialogHeader>
          <DialogTitle className="font-headline text-2xl">
            AI Summary for {fileName || 'File'}
          </DialogTitle>
          <DialogDescription>
            Key points identified by the AI summarization tool.
          </DialogDescription>
        </DialogHeader>
        <ScrollArea className="max-h-[60vh] p-1 pr-4">
          {isLoading ? (
            <div className="flex flex-col items-center justify-center h-40">
              <Loader2 className="h-12 w-12 animate-spin text-primary mb-4" />
              <p className="text-muted-foreground">Generating summary...</p>
            </div>
          ) : summary ? (
            <div className="prose prose-sm max-w-none whitespace-pre-wrap">
              <p>{summary}</p>
            </div>
          ) : (
            <p className="text-muted-foreground">No summary available or an error occurred.</p>
          )}
        </ScrollArea>
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Close
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

export default SummarizeModal;
