'use client';

import type React from 'react';
import type { FileNode } from '@/types';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { ScrollArea } from '@/components/ui/scroll-area';

interface PdfViewerProps {
  selectedFile: FileNode | null;
}

const PdfViewer: React.FC<PdfViewerProps> = ({ selectedFile }) => {
  if (!selectedFile) {
    return (
      <Card className="h-full flex items-center justify-center shadow-lg">
        <CardContent className="text-center">
          <p className="text-lg text-muted-foreground p-8">Select a file to view its content.</p>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="h-full flex flex-col shadow-lg overflow-hidden">
      <CardHeader>
        <CardTitle className="font-headline text-2xl truncate">{selectedFile.name}</CardTitle>
        <CardDescription>Path: {selectedFile.path}</CardDescription>
      </CardHeader>
      <CardContent className="flex-1 p-0">
        <ScrollArea className="h-full p-6">
          <div className="prose prose-sm max-w-none">
            <h3 className="text-xl font-semibold mb-4 font-headline">Embedded PDF Viewer Placeholder</h3>
            <p className="mb-2">
              The content of <strong>{selectedFile.name}</strong> would be displayed here.
            </p>
            <p className="text-muted-foreground text-sm mb-4">
              Actual PDF rendering requires a dedicated library or iframe setup with hosted PDF files.
            </p>
            <div className="bg-muted p-4 rounded-md border">
              <h4 className="font-semibold mb-2">Simulated Content:</h4>
              <p className="text-sm">{selectedFile.contentPreview || "No content preview available."}</p>
            </div>
          </div>
        </ScrollArea>
      </CardContent>
    </Card>
  );
};

export default PdfViewer;
